@app.get("/webhook")
async def verify_webhook(request: Request):
    params = request.query_params
    mode = params.get("hub.mode")
    token = params.get("hub.verify_token")
    challenge = params.get("hub.challenge")
    logger.info("Webhook verification request received")
    if mode == "subscribe" and token == VERIFY_TOKEN:
        logger.info("Webhook verification successful")
        return PlainTextResponse(challenge or "",status_code=200,)
    logger.warning("Webhook verification failed")
    raise HTTPException(status_code=403,detail="Verification failed",)

def verify_meta_signature(body: bytes,signature: str | None,) -> bool:
    if not META_APP_SECRET:
        logger.warning("META_APP_SECRET is not configured. Skipping signature validation.")
        return True
    if not signature:
        return False
    expected = hmac.new(
        META_APP_SECRET.encode("utf-8"),
        body,
        hashlib.sha256,
    ).hexdigest()
    expected_signature = f"sha256={expected}"
    return hmac.compare_digest(
        expected_signature,
        signature,
    )

@app.post("/webhook")
async def instagram_webhook(request: Request):
    body = await request.body()
    signature = request.headers.get("X-Hub-Signature-256")
    if not verify_meta_signature(body,signature,):
        logger.warning("Invalid Meta webhook signature")
        raise HTTPException(status_code=403,detail="Invalid signature",)
    try:
        payload = await request.json()
    except Exception:
        raise HTTPException(status_code=400,detail="Invalid JSON",)

    logger.info("Instagram webhook received: %s",payload,)
    try:
        await process_webhook(payload)
    except Exception:
        logger.exception("Error processing Instagram webhook")
    return {"status": "ok"}

async def process_webhook(payload: Dict[str, Any]):
    logger.info("Processing webhook payload")
    entries = payload.get("entry", [])
    if not entries:
        logger.info("No entry objects found")
        return

    for entry in entries:
        # Some webhook structures contain messaging events
        # directly under "messaging".
        messaging_events = entry.get("messaging",[],)
        for event in messaging_events:
            await process_messaging_event(event)

        # Some configurations may provide changes.
        changes = entry.get("changes",[],)
        for change in changes:
            await process_change_event(change)

async def process_messaging_event(event: Dict[str, Any]):
    logger.info("Messaging event: %s",event,)

    sender = event.get("sender", {})
    sender_id = sender.get("id")

    if not sender_id:
        logger.warning("No sender ID found")
        return

    message = event.get("message",{},)
    text = message.get("text")
    if not text:
        logger.info("Message does not contain text")
        return

    text = text.strip()
    logger.info("Message from %s: %s",sender_id,text,)
    add_message(sender_id,"user",text,)

    reply = generate_reply(sender_id,text,)
    add_message(sender_id, "assistant", reply)
    await send_instagram_message(recipient_id=sender_id, message=reply,)

async def process_change_event(change: Dict[str, Any]):
    logger.info("Instagram change event: %s" % change)
    field = change.get("field")
    value = change.get("value", {})
    logger.info("Change field=%s value=%s" % (field,value))

def generate_reply(user_id: str,text: str,) -> str:
    message = text.lower().strip()
    session = get_session(user_id)
    if message in {"hi", "hello", "hey", "hii", "helo"}:
        return (
            "Hey! 👋\n"
            "Nice to hear from you.\n"
            "How can I help?"
        )

    if "how are you" in message:
        return (
            "I'm doing great 😄\n"
            "What are you up to?"
        )

    if message in {"help", "menu", "options",}:
        return (
            "Sure! 😊\n\n"
            "You can say:\n"
            "• Hello\n"
            "• About me\n"
            "• Help"
        )

    if ("about me" in message or message == "about"):
        return ("I'm Uday's personal Instagram bot 🤖")

    message_count = len(session["messages"])

    return (
        f"I received your message: "
        f"\"{text}\"\n\n"
        f"This is my current basic bot. "
        f"You are conversation message "
        f"#{message_count}."
    )

async def send_instagram_message(recipient_id: str,message: str,):
    if not INSTAGRAM_ACCESS_TOKEN:
        logger.error("INSTAGRAM_ACCESS_TOKEN is not configured")
        return

    if not INSTAGRAM_ACCOUNT_ID:
        logger.error("INSTAGRAM_ACCOUNT_ID is not configured")
        return

    url = (
        f"{GRAPH_BASE_URL}/"
        f"{INSTAGRAM_ACCOUNT_ID}/messages"
    )

    payload = {
        "recipient": {
            "id": recipient_id
        },
        "message": {
            "text": message
        },
    }

    headers = {
        "Authorization": (
            f"Bearer {INSTAGRAM_ACCESS_TOKEN}"
        ),
        "Content-Type": "application/json",
    }

    logger.info("Sending Instagram message to %s",recipient_id,)
    async with httpx.AsyncClient(timeout=30) as client:
        response = await client.post(url, json=payload,headers=headers,)

    logger.info("Instagram API response: %s %s" % (response.status_code, response.text))
    if response.status_code >= 400:
        logger.error("Instagram API error: %s" % response.text)
        return
    logger.info("Instagram message sent successfully")

